import { atom, update, read } from 'claude-code'
import type { Register } from 'claude-code'

import type { Mascot, Member, Message } from '../types'
import {
  BODY_ROWS,
  COORDINATOR,
  MAX_CREW,
  MAX_RAILS,
  MAX_TALK,
  MSG_MS,
  RAIL_PX,
  SLOT_COLS,
  SLOT_H,
  bubbleOf,
  buildView,
  labelOf,
  railText,
  railsSvg,
  resolveTarget,
  slotSvg,
  layoutFor,
  snippet
} from './layout'
import { DEFAULT_LOOK, HIDDEN_KEY, describeLook, folderKey, helpText, isLook, parseLookArgs, randomLook } from './look'
import { LINGER_MS, TERM_COLS, TERM_ROWS, cellsOf, phrase } from './sprite'

const crew = atom({ plugin: 'subagent-crew', key: 'crew' } as const, [] as Member[])
const talk = atom({ plugin: 'subagent-crew', key: 'talk' } as const, [] as Message[])
const me = atom({ plugin: 'subagent-crew', key: 'me' } as const, { say: 'ready', startedAt: 0 } as Mascot)
const look = atom({ plugin: 'subagent-crew', key: 'look' } as const, DEFAULT_LOOK)
const folder = atom({ plugin: 'subagent-crew', key: 'folder' } as const, '')
const hidden = atom({ plugin: 'subagent-crew', key: 'hidden' } as const, false)

let sequence = 0

// A failure in our own bookkeeping must never cost the real result or the real call.
async function quietly(work: () => Promise<unknown>) {
  try {
    await work()
  } catch {
    return
  }
}

// One message between two characters. Only a short snippet is kept, in memory, for a few seconds.
async function send($: any, from: string, to: string, text: string) {
  const at = await $.clock.now()
  const id = `${from}>${to}#${++sequence}`

  await update($, talk, list =>
    [...list.filter(t => at - t.at < MSG_MS), { id, from, to, text: snippet(text) || '…', at }].slice(-MAX_TALK)
  )
  $.clock.after(MSG_MS, () => update($, talk, list => list.filter(t => t.id !== id)))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'crew-demo', description: 'Preview the subagent characters' })
    await $.command.register({ name: 'crew-look', description: 'Change the coordinator character for this folder' })

    const result = await next(e)

    await quietly(async () => {
      const saved = await $.store.get(folderKey(e.cwd))
      const off = await $.store.get(HIDDEN_KEY)
      const now = await $.clock.now()

      await update($, hidden, () => off === true)
      await update($, folder, () => e.cwd)
      await update($, look, () => (isLook(saved) ? saved : DEFAULT_LOOK))
      await update($, me, () => ({ say: 'ready', startedAt: now }))
    })

    return result
  })

  on('agent.spawn', async ($, e, next) => {
    const r = await next(e)

    await quietly(async () => {
      const id = r.agentId

      if (!id) return

      const startedAt = await $.clock.now()
      const parent = e.parentAgentId ?? COORDINATOR

      await update($, crew, list =>
        [
          ...list.filter(m => m.id !== id),
          { id, label: e.description, type: e.subagentType, name: e.name, parent, status: 'running' as const, say: 'starting…', startedAt }
        ].slice(-MAX_CREW)
      )
      await send($, parent, id, e.description)
    })

    return r
  })

  on('tool.call', async ($, e, next) => {
    await quietly(async () => {
      const id = e.agentId

      const say = phrase(e.tool)

      // Only write when the words change, so a burst of tool calls does not redraw the band for nothing.
      if (id) {
        if ((await read($, crew)).some(m => m.id === id && m.status === 'running' && m.say !== say)) {
          await update($, crew, list => list.map(m => (m.id === id && m.status === 'running' ? { ...m, say } : m)))
        }
      } else if ((await read($, me)).say !== say) {
        await update($, me, m => ({ ...m, say }))
      }
    })

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    await quietly(async () => {
      const id = e.agentId

      if (!id) {
        await update($, me, m => ({ ...m, say: 'ready' }))

        return
      }

      const doneAt = await $.clock.now()
      const isStopped = e.isAborted
      const parent = (await read($, crew)).find(m => m.id === id)?.parent ?? COORDINATOR

      await update($, crew, list =>
        list.map(m =>
          m.id === id ? { ...m, status: isStopped ? 'stopped' : 'done', say: isStopped ? 'stopped' : 'done ✓', doneAt } : m
        )
      )

      if (!isStopped) await send($, id, parent, snippet(e.answer) || 'done')

      $.clock.after(LINGER_MS, () => update($, crew, list => list.filter(m => m.id !== id)))
    })

    return next(e)
  })

  on('session.send', async ($, e, next) => {
    const result = await next(e)

    await quietly(async () => {
      const to = resolveTarget(await read($, crew), e.to)
      const from = e.agentId ?? COORDINATOR

      if (to && to !== from) await send($, from, to, e.text)
    })

    return result
  })

  // /crew-demo: four fake agents that talk, work, message each other, finish and leave, to see the look
  // without real subagents.
  on('command.run', { command: 'crew-demo' }, async $ => {
    const stamp = await $.clock.now()
    const cast = [
      { label: 'Explore repo', type: 'explore', tool: 'Read', after: 5000, reply: 'found 3 files' },
      { label: 'Run tests', type: 'tester', tool: 'Bash', after: 8000, reply: '14 tests pass ✓' },
      { label: 'Review diff', type: 'reviewer', tool: 'Grep', after: 11000, reply: 'looks good' },
      { label: 'Write docs', type: 'writer', tool: 'Edit', after: 14000, reply: 'README updated' }
    ]
    const ids = cast.map((_, i) => `demo-${stamp}-${i}`)

    for (const [i, c] of cast.entries()) {
      const id = ids[i]
      const say = (ms: number, text: string) =>
        $.clock.after(ms, () => update($, crew, list => list.map(m => (m.id === id && m.status === 'running' ? { ...m, say: text } : m))))

      await update($, crew, list => [
        ...list,
        { id, label: c.label, type: c.type, parent: COORDINATOR, status: 'running', say: 'starting…', startedAt: stamp }
      ])

      if (i === 0) await send($, COORDINATOR, id, c.label)
      else $.clock.after(i * 700, () => send($, COORDINATOR, id, c.label))

      say(1500, phrase(c.tool))
      say(c.after - 1800, 'finishing…')
      $.clock.after(c.after, async () => {
        await update($, crew, list => list.map(m => (m.id === id ? { ...m, status: 'done', say: 'done ✓', doneAt: stamp + c.after } : m)))
        await send($, id, COORDINATOR, c.reply)
      })
      $.clock.after(c.after + LINGER_MS, () => update($, crew, list => list.filter(m => m.id !== id)))
    }

    $.clock.after(6500, () => send($, ids[2], ids[1], '1 issue found'))

    return { text: 'Four demo characters are on their way.' }
  })

  // /crew-look: show or change the coordinator's colors, kept per folder.
  on('command.run', { command: 'crew-look' }, async ($, e) => {
    const cmd = parseLookArgs(e.args ?? '')
    const current = await read($, look)

    if (cmd.kind === 'error') return { text: cmd.text }
    if (cmd.kind === 'show') return { text: `Coordinator for this folder: ${describeLook(current)}.\n\n${helpText()}` }

    if (cmd.kind === 'off' || cmd.kind === 'on') {
      if (cmd.kind === 'off') await $.store.set(HIDDEN_KEY, true)
      else await $.store.delete(HIDDEN_KEY)

      await update($, hidden, () => cmd.kind === 'off')

      return { text: cmd.kind === 'off' ? 'The crew is hidden everywhere. /crew-look on brings it back.' : 'The crew is back.' }
    }

    const key = folderKey(await read($, folder))
    let changed = DEFAULT_LOOK

    if (cmd.kind === 'reset') {
      await $.store.delete(key)
    } else {
      const saved = await $.store.get(key)
      const base = isLook(saved) ? saved : current

      changed = cmd.kind === 'random' ? randomLook(String(await $.clock.now())) : { ...base, ...cmd.changes }
      await $.store.set(key, changed)
    }

    await update($, look, () => changed)

    return { text: `${cmd.kind === 'reset' ? 'Back to the default.' : 'Saved for this folder.'} Coordinator: ${describeLook(changed)}.` }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const inner = await next(e)

    if (e.props.hasSurvey) return inner

    try {
      if (await read($, hidden)) return inner

      const now = await $.clock.now()
      const members = await read($, crew)
      const { slots, gutter } = layoutFor(e.props.bodyColumns)
      const maxRails =
        e.surface === 'terminal' ? Math.max(0, Math.min(MAX_RAILS, e.props.maxRows - 1 - BODY_ROWS)) : MAX_RAILS
      const view = buildView({
        me: await read($, me),
        look: await read($, look),
        crew: members,
        talk: await read($, talk),
        slots,
        now,
        maxRails,
        busy: e.props.isWorking || members.some(m => m.status === 'running')
      })

      if (e.surface === 'desktop') {
        const { Box, Svg, Text } = $.ui.resolve(e)
        const said = view.routes.map(r => `${view.seats[r.from].type} to ${view.seats[r.to].type}: ${r.text}`).join('; ')

        return (
          <Box flexDirection="column">
            {inner}
            <Box width="100%" flexDirection="column" alignItems="flex-end">
              {view.routes.length > 0 && (
                <Svg key="routes" source={railsSvg(view.routes, view.seats.length)} alt={said} height={view.routes.length * RAIL_PX} />
              )}
              <Box>
                {view.seats.map((s, i) => (
                  <Svg key={s.id} source={slotSvg(s, now, labelOf(s, i, view))} alt={`${s.type}: ${s.say}`} height={SLOT_H} />
                ))}
              </Box>
              {view.extra > 0 && <Text dimColor>+{view.extra} more</Text>}
            </Box>
          </Box>
        )
      }

      if (e.surface === 'terminal') {
        const { Box, Raster, Text } = $.ui.resolve(e)

        return (
          <Box flexDirection="column">
            {inner}
            <Box width="100%" flexDirection="column" alignItems="flex-end">
              <Box width={gutter + SLOT_COLS * slots} flexDirection="column">
                {view.routes.map((r, i) => (
                  <Text key={`route-${i}`} color={r.color} wrap="truncate">
                    {railText(r, slots, gutter)}
                  </Text>
                ))}
                {view.routes.length === 0 && maxRails > 0 && <Text> </Text>}
                <Box>
                  <Box width={gutter} />
                  {view.seats.map((s, i) => (
                    <Box key={s.id} width={SLOT_COLS} flexDirection="column" alignItems="center">
                      <Text dimColor italic wrap="truncate">
                        {bubbleOf(s)}
                      </Text>
                      <Raster key={`crew-${s.id}`} columns={TERM_COLS} rows={TERM_ROWS} cells={cellsOf(s.look)} />
                      <Text dimColor wrap="truncate">
                        {labelOf(s, i, view)}
                      </Text>
                    </Box>
                  ))}
                </Box>
                {view.extra > 0 && (
                  <Box justifyContent="flex-end">
                    <Text dimColor>+{view.extra} more</Text>
                  </Box>
                )}
              </Box>
            </Box>
          </Box>
        )
      }

      return inner
    } catch {
      return inner
    }
  })
}

