import type { Look, Mascot, Member, Message } from '../types'
import { COLS, LINGER_MS, ROWS, UNIT, blinkDelay, clip, esc, lookOf, rectsOf, sec } from './sprite'

export const COORDINATOR = 'coordinator'

// The band is a row of slots, the coordinator first. A terminal slot is 16 cells wide; a desktop slot is 128 px.
export const SLOT_COLS = 16
export const SLOT_PX = 150
export const MAX_SLOTS = 8

// A message route stays up for this long, and at most this many show at once.
export const MSG_MS = 8000
export const MAX_RAILS = 3

// A subagent that never reports back is dropped after this long, and the row never tracks more than this many.
export const STALE_RUN_MS = 60 * 60 * 1000
export const MAX_CREW = 40
export const MAX_TALK = 12

export const BUBBLE_CHARS = 12
export const LABEL_CHARS = 11
export const SNIPPET_CHARS = 28

// Terminal rows besides the routes: the bubble, the character, and its label.
export const BODY_ROWS = 6

// Desktop pixel sizes.
export const RAIL_PX = 26
const CHAR_Y = 24
export const SLOT_H = CHAR_Y + ROWS * UNIT + 16

// Free columns kept to the left of the slots, where a long message sits beside its route.
export const MIN_GUTTER = 14
export const MAX_GUTTER = 34

// How many slots fit, and how wide the gutter on their left is.
export const layoutFor = (columns: number) => {
  const slots = Math.min(MAX_SLOTS, Math.max(2, Math.floor((columns - MIN_GUTTER) / SLOT_COLS)))
  const gutter = Math.max(0, Math.min(MAX_GUTTER, columns - SLOT_COLS * slots))

  return { slots, gutter }
}

// The short version of a message that a route shows: its first line, plain, cut to fit.
export const snippet = (text: string) => {
  const line = text.split('\n').map(l => l.trim()).find(l => l.length > 0) ?? ''
  const plain = line
    .replace(/^[#>*\-•✔✓✖\s]+/, '')
    .replace(/[*_`]/g, '')
    .replace(/[^\x20-\x7E\u00A1-\u024F…✓✔✖→·–—‘’“”]/g, '')
    .replace(/\s+/g, ' ')
    .trim()

  return clip(plain, SNIPPET_CHARS)
}

// A route takes its sender's hair color, nudged so it stays readable on a dark or a light background.
export const routeColor = (hair: number) => {
  const rgb = [(hair >> 16) & 255, (hair >> 8) & 255, hair & 255]
  const luma = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255
  const tuned = luma < 0.35 ? rgb.map(c => Math.round(c + (255 - c) * 0.5)) : luma > 0.78 ? rgb.map(c => Math.round(c * 0.7)) : rgb

  return `#${tuned.map(c => c.toString(16).padStart(2, '0')).join('')}`
}

export type Seat = {
  id: string
  type: string
  look: Look
  say: string
  status: Member['status']
  animated: boolean
  startedAt?: number
  doneAt?: number
}

export type Route = { from: number; to: number; text: string; color: string }

export type View = {
  seats: Seat[]
  extra: number
  routes: Route[]
  senders: Set<number>
  receivers: Set<number>
}

type ViewInput = {
  me: Mascot
  look: Look
  crew: Member[]
  talk: Message[]
  slots: number
  now: number
  maxRails: number
  busy?: boolean
}

// Who is on the band and which message routes to draw: the coordinator first, then the newest subagents
// that fit. A message is drawn only while it is fresh and both ends are on the band.
export const buildView = ({ me, look, crew: all, talk, slots, now, maxRails, busy = true }: ViewInput): View => {
  const crew = all.filter(m => m.status !== 'running' || now - (m.startedAt ?? now) < STALE_RUN_MS)
  const shown = crew.slice(-(slots - 1))
  const seats: Seat[] = [
    // The coordinator is always on screen, so it only animates while something is happening.
    { id: COORDINATOR, type: COORDINATOR, look, say: me.say, status: 'running', animated: busy, startedAt: me.startedAt },
    ...shown.map(m => ({
      id: m.id,
      type: m.type,
      look: lookOf(m.id),
      say: m.say,
      status: m.status,
      animated: m.status === 'running',
      startedAt: m.startedAt,
      doneAt: m.doneAt
    }))
  ]
  const index = new Map(seats.map((s, i) => [s.id, i]))
  const fresh = talk.filter(t => now - t.at < MSG_MS && t.from !== t.to && index.has(t.from) && index.has(t.to))
  const live = maxRails > 0 ? fresh.slice(-maxRails) : []
  const routes = live.map(t => {
    const from = index.get(t.from) as number
    const to = index.get(t.to) as number

    return { from, to, text: t.text, color: routeColor(seats[from].look.hair) }
  })

  return {
    seats,
    extra: crew.length - shown.length,
    routes,
    senders: new Set(routes.map(r => r.from)),
    receivers: new Set(routes.map(r => r.to))
  }
}

export const bubbleOf = (seat: Seat) => `(${clip(seat.say, BUBBLE_CHARS)})`

// The name under a character: a marker before it while a message is coming in, and after it while one goes out.
export const labelOf = (seat: Seat, i: number, view: View) =>
  `${view.receivers.has(i) ? '▸ ' : ''}${clip(seat.type, LABEL_CHARS)}${view.senders.has(i) ? ' ▴' : ''}`

// Terminal: one text line that runs from the sender's slot to the recipient's, a dot at the sender, an
// arrowhead at the recipient. The message sits on the line when it fits; otherwise it ends just left of the
// line, over the gutter, so it can never sit above a different character than the line belongs to.
export const railText = (route: Route, slots: number, gutter = 0) => {
  const cells = Array<string>(gutter + SLOT_COLS * slots).fill(' ')
  const x0 = gutter + route.from * SLOT_COLS + SLOT_COLS / 2
  const x1 = gutter + route.to * SLOT_COLS + SLOT_COLS / 2
  const lo = Math.min(x0, x1)
  const hi = Math.max(x0, x1)

  for (let x = lo; x <= hi; x++) cells[x] = '─'

  cells[x0] = '●'
  cells[x1] = x1 > x0 ? '►' : '◄'

  const put = (start: number, text: string) => [...text].forEach((ch, i) => (cells[start + i] = ch))
  const inside = hi - lo - 5
  const leftRoom = lo - 2
  const len = route.text.length

  if (len === 0) return cells.join('')

  if (len <= inside) {
    const start = lo + 3 + Math.floor((inside - len) / 2)

    cells[start - 1] = ' '
    put(start, route.text)
    cells[start + len] = ' '
  } else if (leftRoom >= 3 && leftRoom >= Math.min(len, inside)) {
    const text = clip(route.text, leftRoom)

    put(lo - 1 - text.length, text)
  } else if (inside >= 3) {
    const text = clip(route.text, inside)

    cells[lo + 2] = ' '
    put(lo + 3 + Math.floor((inside - text.length) / 2), text)
  }

  return cells.join('')
}

// Desktop: one slot, a bubble over a character over its name. Animated by status.
export const slotSvg = (seat: Seat, now: number, label: string) => {
  const isRunning = seat.status === 'running'
  const age = Math.max(0, now - (seat.startedAt ?? now)) / 1000
  const since = Math.max(0, now - (seat.doneAt ?? now)) / 1000
  const text = clip(seat.say, BUBBLE_CHARS)
  const pillW = Math.max(36, Math.round(text.length * 5.8) + 18)
  const mid = SLOT_PX / 2
  const art = !isRunning
    ? `<g class="spin">${rectsOf(seat.look)}</g>`
    : seat.animated
      ? `<g class="pop"><g class="bob">${rectsOf(seat.look)}</g></g>`
      : `<g>${rectsOf(seat.look)}</g>`
  const blink = seat.animated && isRunning || !isRunning
    ? `.eye{transform-box:fill-box;transform-origin:center;animation:blink 4.5s ${blinkDelay(seat.id)} infinite}`
    : ''
  const body = [
    `<rect x="${mid - pillW / 2}" y="2" width="${pillW}" height="16" rx="8" fill="rgba(128,128,128,.2)"/>`,
    `<text x="${mid}" y="13.4" text-anchor="middle" font-size="10" font-family="-apple-system,system-ui,sans-serif" fill="#9a9a9a">${esc(text)}</text>`,
    `<circle cx="${mid}" cy="21" r="1.4" fill="rgba(128,128,128,.35)"/>`,
    `<g transform="translate(${mid - (COLS * UNIT) / 2} ${CHAR_Y}) scale(${UNIT})">${art}</g>`,
    `<text x="${mid}" y="${CHAR_Y + ROWS * UNIT + 11}" text-anchor="middle" font-size="9" font-family="-apple-system,system-ui,sans-serif" fill="#8a8a8a">${esc(label)}</text>`
  ].join('')

  return [
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SLOT_PX} ${SLOT_H}" width="${SLOT_PX}" height="${SLOT_H}">`,
    '<style>',
    `.pop{transform-origin:${COLS / 2}px ${ROWS}px;animation:pop .45s cubic-bezier(.3,1.7,.5,1) ${sec(-age)} both}`,
    `.bob{animation:bob .8s ease-in-out ${sec(-(age % 0.8))} infinite}`,
    `.spin{transform-origin:${COLS / 2}px ${ROWS / 2}px;animation:spin .8s linear ${sec(-since)} 1}`,
    `.fade{animation:fade 1s ${sec((LINGER_MS - 1000) / 1000 - since)} forwards}`,
    blink,
    '@keyframes pop{0%{transform:scale(0)}100%{transform:scale(1)}}',
    '@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-.2px)}}',
    '@keyframes spin{0%,100%{transform:scaleX(1)}25%,75%{transform:scaleX(0)}50%{transform:scaleX(-1)}}',
    '@keyframes fade{to{opacity:0}}',
    '@keyframes blink{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}',
    '</style>',
    isRunning ? body : `<g class="fade">${body}</g>`,
    '</svg>'
  ].join('')
}

// Desktop: the routes above the row, one line each with a dot, an arrowhead, and the message in a chip on the
// line, clipped to fit so it always sits between the two characters it belongs to.
export const railsSvg = (routes: Route[], slots: number) => {
  const width = slots * SLOT_PX
  const height = routes.length * RAIL_PX
  const charPx = 5.8
  const parts = routes.map((r, i) => {
    const y = i * RAIL_PX + RAIL_PX / 2
    const x0 = (r.from + 0.5) * SLOT_PX
    const x1 = (r.to + 0.5) * SLOT_PX
    const lo = Math.min(x0, x1)
    const hi = Math.max(x0, x1)
    const stroke = `stroke="${r.color}" stroke-width="2" stroke-linecap="round"`
    const seg = (a: number, b: number) => `<line x1="${a}" y1="${y}" x2="${b}" y2="${y}" ${stroke}/>`
    const head =
      x1 > x0 ? `${x1 - 10},${y - 5} ${x1},${y} ${x1 - 10},${y + 5}` : `${x1 + 10},${y - 5} ${x1},${y} ${x1 + 10},${y + 5}`
    const text = clip(r.text, Math.max(0, Math.floor((hi - lo - 24 - 16) / charPx)))
    const chipW = text.length >= 2 ? Math.round(text.length * charPx) + 16 : 0
    const left = (lo + hi) / 2 - chipW / 2
    const line = chipW ? seg(lo, left) + seg(left + chipW, hi) : seg(lo, hi)
    const chip = chipW
      ? `<rect x="${left}" y="${y - 8}" width="${chipW}" height="16" rx="8" fill="none" stroke="${r.color}" stroke-width="1"/>` +
        `<text x="${left + chipW / 2}" y="${y + 3.4}" text-anchor="middle" font-size="10" font-family="-apple-system,system-ui,sans-serif" fill="${r.color}">${esc(text)}</text>`
      : ''

    return `${line}<circle cx="${x0}" cy="${y}" r="4" fill="${r.color}"/><polygon points="${head}" fill="${r.color}"/>${chip}`
  })

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">${parts.join('')}</svg>`
}

// Who a message is for: the coordinator, or a subagent by id, name, or type. Nothing when nobody on the band matches.
export const resolveTarget = (crew: Member[], to: string): string | undefined => {
  if (to === COORDINATOR || /^(main|lead|team-lead|coordinator)$/i.test(to)) return COORDINATOR

  return crew.find(m => m.id === to || m.name === to)?.id ?? crew.find(m => m.type === to)?.id
}

