import type { Look } from '../types'
import { EYES, HAIR, SKIN, pick, seeded } from './sprite'

// The coordinator's look until the person changes it.
export const DEFAULT_LOOK: Look = { hair: 0x3b6fd8, skin: 0xefc2a0, eyes: 0x4a2f1c }

const named = (names: string[], values: number[]): Record<string, number> =>
  Object.fromEntries(names.map((n, i) => [n, values[i]]))

export const HAIR_NAMES = named(
  ['black', 'darkbrown', 'brown', 'chestnut', 'blonde', 'red', 'gray', 'white', 'blue', 'pink', 'green', 'purple'],
  HAIR
)
export const SKIN_NAMES = named(['porcelain', 'fair', 'tan', 'medium', 'brown', 'deep', 'dark', 'ebony'], SKIN)
export const EYE_NAMES = named(['brown', 'blue', 'green', 'hazel', 'gray', 'violet'], EYES)

const PARTS: Record<string, { part: keyof Look; names: Record<string, number> }> = {
  hair: { part: 'hair', names: HAIR_NAMES },
  skin: { part: 'skin', names: SKIN_NAMES },
  eyes: { part: 'eyes', names: EYE_NAMES },
  eye: { part: 'eyes', names: EYE_NAMES }
}

const hex6 = (n: number) => `#${n.toString(16).padStart(6, '0')}`

// A color given as a name from the part's list, or as #rrggbb or #rgb.
export const parseColor = (raw: string, names: Record<string, number>): number | undefined => {
  const v = raw.trim().toLowerCase().replace(/[^a-z0-9#]/g, '')

  if (v in names) return names[v]

  const m = /^#?([0-9a-f]{6})$/.exec(v)
  const short = /^#?([0-9a-f]{3})$/.exec(v)

  if (m) return parseInt(m[1], 16)
  if (short) return parseInt([...short[1]].map(c => c + c).join(''), 16)

  return undefined
}

export const nameOf = (value: number, names: Record<string, number>) =>
  Object.entries(names).find(([, v]) => v === value)?.[0] ?? hex6(value)

export const describeLook = (look: Look) =>
  `hair ${nameOf(look.hair, HAIR_NAMES)}, skin ${nameOf(look.skin, SKIN_NAMES)}, eyes ${nameOf(look.eyes, EYE_NAMES)}`

export const isLook = (v: unknown): v is Look =>
  typeof v === 'object' &&
  v !== null &&
  ['hair', 'skin', 'eyes'].every(k => typeof (v as Record<string, unknown>)[k] === 'number')

export const helpText = () =>
  [
    'Change the coordinator for this folder: /crew-look hair=blue skin=tan eyes=green',
    'Use a name or a hex color such as #ff8800. /crew-look random picks a look, /crew-look reset goes back.',
    '/crew-look off hides the whole crew everywhere, and /crew-look on brings it back.',
    `hair: ${Object.keys(HAIR_NAMES).join(', ')}`,
    `skin: ${Object.keys(SKIN_NAMES).join(', ')}`,
    `eyes: ${Object.keys(EYE_NAMES).join(', ')}`
  ].join('\n')

export type LookCommand =
  | { kind: 'show' }
  | { kind: 'off' }
  | { kind: 'on' }
  | { kind: 'reset' }
  | { kind: 'random' }
  | { kind: 'set'; changes: Partial<Look> }
  | { kind: 'error'; text: string }

// "hair=blue skin=tan", or "hair blue skin tan", or a single word: random, reset, show.
export const parseLookArgs = (args: string): LookCommand => {
  const tokens = args.replace(/\s*=\s*/g, '=').trim().split(/\s+/).filter(Boolean)

  if (tokens.length === 0 || (tokens.length === 1 && ['show', 'help', '?'].includes(tokens[0].toLowerCase()))) {
    return { kind: 'show' }
  }

  if (tokens.length === 1 && tokens[0].toLowerCase() === 'off') return { kind: 'off' }
  if (tokens.length === 1 && tokens[0].toLowerCase() === 'on') return { kind: 'on' }
  if (tokens.length === 1 && tokens[0].toLowerCase() === 'reset') return { kind: 'reset' }
  if (tokens.length === 1 && tokens[0].toLowerCase() === 'random') return { kind: 'random' }

  const changes: Partial<Look> = {}

  for (let i = 0; i < tokens.length; i++) {
    let [key, value] = tokens[i].split('=')

    if (value === undefined && PARTS[key.toLowerCase()] && tokens[i + 1] !== undefined) {
      value = tokens[++i]
    }

    const spec = PARTS[key.toLowerCase()]

    if (!spec) return { kind: 'error', text: `Don't know "${key}". Use hair, skin, or eyes.` }
    if (value === undefined) return { kind: 'error', text: `Give ${key} a color, like ${key}=${Object.keys(spec.names)[0]}.` }

    const color = parseColor(value, spec.names)

    if (color === undefined) {
      return { kind: 'error', text: `No ${key} color "${value}". Try: ${Object.keys(spec.names).join(', ')}, or a hex like #ff8800.` }
    }

    changes[spec.part] = color
  }

  return { kind: 'set', changes }
}

// Where this folder's coordinator look is kept, by a short hash of the folder path.
export const HIDDEN_KEY = 'crew:hidden'

export const folderKey = (cwd: string) => {
  let h = 2166136261

  for (const ch of cwd) {
    h ^= ch.charCodeAt(0)
    h = Math.imul(h, 16777619)
  }

  return `look:${(h >>> 0).toString(16)}`
}

export const randomLook = (seed: string): Look => {
  const rand = seeded(seed)

  return { hair: pick(rand, HAIR), skin: pick(rand, SKIN), eyes: pick(rand, EYES) }
}

