import type { Look } from '../types'

// How long a finished character lingers before it leaves.
export const LINGER_MS = 6000

// The character, one letter per pixel: H hair, B body, A arm, L leg, E eye.
// Both surfaces draw this same grid, so the character looks the same on each.
export const MAP = [
  '.HHH.',
  'BEBEB',
  'ABBBA',
  '.L.L.'
]
export const COLS = MAP[0].length
export const ROWS = MAP.length

// Desktop: screen pixels per art pixel.
export const UNIT = 6

// Terminal: a cell is about twice as tall as it is wide, so an art pixel is two cells wide and one tall.
export const CELLS_PER_PIXEL = 2
export const TERM_COLS = COLS * CELLS_PER_PIXEL
export const TERM_ROWS = ROWS

export const SKIN = [0xf6d7c3, 0xefc2a0, 0xe0a97c, 0xc98a5e, 0xa8693f, 0x8a5230, 0x6b3e26, 0x4a2a1a]
export const HAIR = [0x1a1410, 0x3b2416, 0x6b4423, 0xa56a2c, 0xd8b15a, 0xc1452b, 0x9aa0a6, 0xe8e4dc, 0x3b6fd8, 0xd85aa6, 0x3fb96a, 0x8a4fd8]
export const EYES = [0x4a2f1c, 0x2f6fd0, 0x2e8b57, 0xb07a2a, 0x7a8a99, 0x6a3fb0]

// What a character says as it picks up each tool. Short, because a bubble sits over one slot.
const PHRASE: Record<string, string> = {
  Read: 'reading…',
  Grep: 'searching…',
  Glob: 'looking…',
  Bash: 'running…',
  Edit: 'editing…',
  Write: 'writing…',
  WebSearch: 'web search…',
  WebFetch: 'fetching…',
  Agent: 'delegating…',
  SendMessage: 'messaging…'
}

export const phrase = (tool: string) =>
  PHRASE[tool] ?? `using ${tool.startsWith('mcp__') ? (tool.split('__').pop() ?? tool) : tool}…`

export const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1)}…` : s)

export const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

// Seeded from the agent id so a character keeps its look across redraws.
export const seeded = (id: string) => {
  let h = 2166136261

  for (const ch of id) {
    h ^= ch.charCodeAt(0)
    h = Math.imul(h, 16777619)
  }

  let a = h >>> 0

  return () => {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t

    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function pick<T>(rand: () => number, items: T[]): T {
  return items[Math.floor(rand() * items.length)]
}

const darken = (c: number, f: number) => {
  const r = Math.round(((c >> 16) & 255) * f)
  const g = Math.round(((c >> 8) & 255) * f)
  const b = Math.round((c & 255) * f)

  return (r << 16) | (g << 8) | b
}

export const hex = (c: number) => `#${c.toString(16).padStart(6, '0')}`

// A subagent's random look, the same every time for the same id.
export const lookOf = (id: string): Look => {
  const rand = seeded(id)
  const skin = pick(rand, SKIN)
  const hair = pick(rand, HAIR)
  const eyes = pick(rand, EYES)

  return { hair, skin, eyes }
}

// The character's pixels as colors (null = empty), row by row. Both surfaces draw from this.
export const pixelsOf = (look: Look) => {
  const shade = darken(look.skin, 0.86)
  const colors: Record<string, number> = { H: look.hair, B: look.skin, A: shade, L: shade, E: look.eyes }

  return MAP.map(row => [...row].map(ch => (ch === '.' ? null : colors[ch])))
}

export const blinkDelay = (id: string) => `${(seeded(id + 'blink')() * 4).toFixed(1)}s`

// A negative animation-delay starts an animation part-way through, so a redraw (which reloads the
// picture) resumes where the character already was instead of replaying pop-in or the spin.
export const sec = (n: number) => `${n.toFixed(2)}s`

// Desktop: one run-length rect per stretch of same-colored pixels; eye pixels carry a class so they can blink.
export const rectsOf = (look: Look) => {
  const out: string[] = []

  pixelsOf(look).forEach((row, y) => {
    let x = 0

    while (x < COLS) {
      const c = row[x]

      if (c === null) {
        x += 1
        continue
      }

      let n = 1
      const isEye = MAP[y][x] === 'E'

      while (!isEye && x + n < COLS && row[x + n] === c && MAP[y][x + n] === MAP[y][x]) n += 1

      out.push(`<rect${isEye ? ' class="eye"' : ''} x="${x}" y="${y}" width="${n}" height="1" fill="${hex(c)}"/>`)
      x += n
    }
  })

  return out.join('')
}

// Terminal: each art pixel is a block of solid-colored cells (a space with a background), so every cell
// is painted edge to edge. No block glyphs, which many fonts draw shorter than the line. Each cell is three
// words: character, foreground, background.
export const DEFAULT = 0x01000000

export const cellWords = (look: Look) => {
  const words = new Uint32Array(TERM_COLS * TERM_ROWS * 3)

  pixelsOf(look).forEach((row, y) => {
    row.forEach((color, x) => {
      for (let k = 0; k < CELLS_PER_PIXEL; k++) {
        const i = (y * TERM_COLS + x * CELLS_PER_PIXEL + k) * 3

        words[i] = 0x20
        words[i + 1] = DEFAULT
        words[i + 2] = color ?? DEFAULT
      }
    })
  })

  return words
}

export const cellsOf = (look: Look) => new Uint8Array(cellWords(look).buffer).toBase64()

